import sys

def solve():
    import sys
    import numpy as np

    def read_input():
        import sys
        input = sys.stdin.read().split()
        n = int(input[0])
        m = int(input[1])
        board = [list(input[i+2]) for i in range(n)]
        return n, m, board

    def is_valid_board(n, m, board):
        for i in range(n):
            for j in range(m):
                if board[i][j] != '.':
                    expected = 'w' if (i + j) % 2 == 0 else 'b'
                    if board[i][j] != expected:
                        return False
        return True

    def try_tile(n, m, board):
        def dfs(x, y, tile_id):
            if x == n:
                return True
            nx, ny = (x, y + 1) if y + 1 < m else (x + 1, 0)
            if board[x][y] == '.':
                return dfs(nx, ny, tile_id)
            if (x, y) in visited:
                return False
            visited.add((x, y))
            for dx, dy, dz in [(0, 1, 2), (0, 2, 1), (1, 0, 2), (2, 0, 1), (1, 2, 0), (2, 1, 0)]:
                if all(0 <= x + di < n and 0 <= y + dj < m and board[x + di][y + dj] == 'b' for di, dj in [(dx, dy), (dx, dz), (dy, dx), (dy, dz), (dz, dx), (dz, dy)]):
                    for di, dj in [(dx, dy), (dx, dz), ((dx + dy) // 2, (dy + dz) // 2)]:
                        if (x + di, y + dj) not in visited:
                            visited.add((x + di, y + dj))
                            tiling[x + di][y + dj] = tile_id
                    if dfs(nx, ny, chr(ord(tile_id) + 1) if tile_id < 'd' else 'a'):
                        return True
                    for di, dj in [(dx, dy), (dx, dz)]:
                        visited.remove((x + di, y + dj))
            visited.remove((x, y))
            return False

        tiling = [['.' for _ in range(m)] for _ in range(n)]
        visited = set()
        for i in range(n):
            for j in range(m):
                tiling[i][j] = board[i][j]
        if dfs(0, 0, 'a'):
            return [''.join(row) for row in tiling]
        return None

    n, m, board = read_input()
    if not is_valid_board(n, m, board):
        print("NO")
        return
    tiling = try_tile(n, m, board)
    if tiling:
        print("YES")
        for row in tiling:
            print(row)
    else:
        print("NO")

solve()
